const wsHandler = async (req: NextRequest) => {
  const token = req.nextUrl.searchParams.get('token');
  if (!token) return new Response('Unauthorized', { status: 401 });
  const session = await verifyToken(token);
  if (!session) return new Response('Unauthorized', { status: 401 });

  const upgradeHeader = req.headers.get('upgrade');
  if (upgradeHeader !== 'websocket') {
    return new Response('Expected Upgrade: websocket', { status: 426 });
  }

  const pair = new WebSocketPair();
  const [server, client] = Object.values(pair);
  const ws = server.accept();
  ws.userId = session.userId;
  connectionRegistry.set(ws, session.userId);
  ws.addEventListener('message', (event) => handleMessage(event, ws));
  ws.addEventListener('close', () => connectionRegistry.delete(ws));
  return new Response(null, { status: 101, webSocket: client });
};
